 {id:"schreib", erweitert:"L02:schreib", cap:"Schreibstellenplan", phase:4, head:["Ausgang","Bedeutung","ab Übung","schreibt (Baustein, einzige Stelle)","Bedingung oder Befehl kommt von","in der Querverweisliste geprüft"], muster:["−PF2","Bad bereit","L02","FB Indication (bis L03 FC), Aufruf im OB1","−BG9 UND −BG10, ODER Lampentest −SF4","ja, eine Schreibstelle"], rows:[["−MB1","Ventil, Hand und Auto","L16"],["−MB2","Ventil, Hand und Auto","L16"],["−MB3","Ventil, Hand und Auto","L16"],["−MB4","Ventil, Hand und Auto","L16"],["−MB5","Ventil, Hand und Auto","L16"],["−MB6","Ventil, Hand und Auto","L16"],["−MB7","Ventil, Hand und Auto","L16"],["−MB8","Ventil, Hand und Auto","L16"],["−MB9","Ventil, Hand und Auto","L16"]], inputs:3},
 {id:"plantdata", erweitert:"L05:plantdata", cap:"Variablenliste PlantData", phase:4, head:["Inhalt","ab Übung","Variablenname","Datentyp","remanent (ja oder nein, warum)","schreibt (Baustein, über den OB1)","liest"], muster:["Betriebsbereitschaft","L05","ready","Bool","nein, nach dem Neustart muss neu gestartet werden","Operation (Output ready)","Indication"], rows:[["Auto-Befehl −MM1 einhängen","L16"],["Auto-Befehl −MM1 lösen","L16"],["Auto-Befehl −MM2 senken","L16"],["Auto-Befehl −MM2 anheben","L16"],["Auto-Befehl −MM3 zum Bad","L16"],["Auto-Befehl −MM3 zum Band","L16"],["Auto-Befehl −MM4 abdecken","L16"],["Auto-Befehl −MM4 öffnen","L16"],["Handbefehl je Bewegung (manHook, manLower … manStopperOpen)","L16"]], inputs:5}
